  showWizard: boolean;
  lastDeviceId: string | null;
  setLanguage: (language: Language) => void;
  setShowWizard: (show: boolean) => void;
  setLastDeviceId: (id: string | null) => void;
  reset: () => void;
}

function useFirstVisit(): {
  isFirstVisit: boolean;
  markWizardCompleted: () => void;
}
